const today = () => new Date().toLocaleDateString('en-CA');
const stamp = () => new Date().toISOString();
const uid = () => crypto?.randomUUID?.() || `${Date.now()}-${Math.random()}`;
// Nama pinguin mengikuti yang diisi pengguna; kalau kosong, pakai "My Penguin".
const petName = p => ((p && p.name) || '').trim() || 'My Penguin';
const fmt = n => new Intl.NumberFormat('id-ID').format(Math.max(0, Math.round(n || 0)));
const read = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const write = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} };
const defaults = {
  target: null, logs: [], reminders: { enabled: true, interval: 90, snoozeUntil: null, permissionAsked: false },
  urine: [], symptoms: [], habits: {}, learning: { completed: [], bookmarks: [] }, achievements: []
};
function useUserData(user) {
  const [profile,setProfile]=useStoredState(userKey(user.id,'profile'), {type:'object',shape:{displayName:{type:'string'},age:{type:'number',nullable:true},sex:{type:'string'},weightKg:{type:'number',nullable:true},heightCm:{type:'number',nullable:true},wakeTime:{type:'string'},sleepTime:{type:'string'}}}, defaultProfile);
  const [assessment,setAssessment]=useStoredState(userKey(user.id,'assessment'), {type:'object',shape:{activityLevel:{type:'string'},exerciseDaysPerWeek:{type:'number'},exerciseIntensity:{type:'string'},sweatingLevel:{type:'string'},hotEnvironment:{type:'string'},pregnancyStatus:{type:'string'},conditions:{type:'array',of:{type:'string'}},hasPrescribedTarget:{type:'boolean'},prescribedMl:{type:'number',nullable:true},prescribedNote:{type:'string'},monitoring:{type:'object',shape:{urineColor:{type:'boolean'},symptoms:{type:'boolean'}}},completedAt:{type:'string',nullable:true}}}, defaultAssessment);
  const [penguin,setPenguin]=useStoredState(userKey(user.id,'penguin'), {type:'object',shape:{name:{type:'string'},mood:{type:'string'},xp:{type:'number'},level:{type:'number'},coins:{type:'number'},streak:{type:'number'},accessories:{type:'object',shape:{owned:{type:'array',of:{type:'string'}},equipped:{type:'array',of:{type:'string'}}}},createdAt:{type:'string',nullable:true}}}, defaultPenguin);
  const [onboarding,setOnboarding]=useStoredState(userKey(user.id,'onboarding'),{type:'object',shape:{personal:{type:'boolean'},assessment:{type:'boolean'},penguin:{type:'boolean'}}},defaultOnboarding);
  const [data,setData]=useState(()=>read(userKey(user.id,'appdata'),defaults));
  useEffect(()=>write(userKey(user.id,'appdata'),data),[data,user.id]);
  const patch=(k,v)=>setData(p=>({...p,[k]:typeof v==='function'?v(p[k]):v}));
  const todayKey = new Date().toLocaleDateString('en-CA');
  const todayTotal = (data.logs || []).filter(x => x.date === todayKey).reduce((sum,x) => sum + (Number(x.ml) || 0), 0);
  const hydrationMood = !data.target ? 'neutral' : todayTotal === 0 ? 'thirsty' : todayTotal >= data.target ? 'happy' : 'neutral';
  const companion = { ...penguin, mood: hydrationMood };
  return {profile,setProfile,assessment,setAssessment,penguin:companion,setPenguin,onboarding,setOnboarding,data,patch};
}
function Button({children,onClick,kind='primary',...p}) { return <button className={`btn ${kind}`} onClick={onClick} {...p}>{children}</button>; }
function Card({children,className=''}) { return <section className={`card ${className}`}>{children}</section>; }
function Field({label,help,children}) { return <label className="field"><span>{label}</span>{children}{help&&<small>{help}</small>}</label>; }
function HeaderBrand(){return <div className="brand"><span className="brand-drop"><AquaryIcon name="water" size={23}/></span><span>AQUARY<small>Seteguk kecil, sehat lebih lama.</small></span></div>}
function Welcome({mode}) {
 const {login,register}=useAuth(), nav=useNavigate(); const [email,E]=useState(''),[password,P]=useState(''),[error,S]=useState(''),[busy,B]=useState(false);
 const submit=async e=>{e.preventDefault();S('');B(true);try{await (mode==='login'?login:register)(email,password);nav('/');}catch(x){S(x.message||'Terjadi kesalahan.');}finally{B(false);}};
 usePageTitle(mode==='login'?'Masuk':'Daftar');
 return <main className="welcome"><div className="welcome-left"><HeaderBrand/><div className="hero-copy"><span className="eyebrow">TEMAN MINUMMU SETIAP HARI</span><h1>Pelan-pelan,<br/><em>jaga dirimu</em> tiap hari.</h1><p>Catat minummu, kenali kesehatan saluran kemih, dan belajar soal ginjal bareng pinguin kecilmu.</p><div className="hero-points"><span><AquaryIcon name="water" size={16}/> Target minum pribadi</span><span><AquaryIcon name="sparkle" size={16}/> Teman pinguin</span><span><AquaryIcon name="book" size={16}/> Belajar kesehatan</span></div></div><div className="hero-penguin"><Penguin mood="happy" size="large"/></div></div><div className="auth-panel"><Card><div className="mobile-brand"><HeaderBrand/></div><span className="eyebrow">{mode==='login'?'SELAMAT DATANG KEMBALI':'MULAI PETUALANGANMU'}</span><h2>{mode==='login'?'Masuk ke AQUARY':'Buat akun AQUARY'}</h2><p className="muted">Perjalanan minummu tersimpan di perangkat ini.</p><form onSubmit={submit}><Field label="Alamat email"><input type="email" required value={email} onChange={e=>E(e.target.value)} placeholder="nama@email.com"/></Field><Field label="Password" help="Minimal 6 karakter. Password disimpan sebagai hash, bukan teks biasa."><input type="password" minLength="6" required value={password} onChange={e=>P(e.target.value)} placeholder="••••••••"/></Field>{error&&<p className="error" role="alert">{error}</p>}<Button disabled={busy}>{busy?'Sebentar ya…':mode==='login'?'Masuk':'Buat akun'}</Button></form><p className="switch-auth">{mode==='login'?'Baru di AQUARY?':'Sudah punya akun?'} <a href={mode==='login'?'/daftar':'/masuk'}>{mode==='login'?'Daftar':'Masuk'}</a></p></Card></div></main>
}
